package com.mamtrex.hospital.emergency;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/emergency-visits") public class EmergencyVisitController { private final EmergencyVisitRepository repo; private final AuditService audit; public EmergencyVisitController(EmergencyVisitRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String patientId, @jakarta.validation.constraints.NotBlank String arrivalAt, @jakarta.validation.constraints.NotBlank String triageLevel, @jakarta.validation.constraints.NotBlank String chiefComplaint, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public EmergencyVisit create(@Valid @RequestBody Request r){var e=repo.save(new EmergencyVisit(r.patientId(), r.arrivalAt(), r.triageLevel(), r.chiefComplaint(), r.status()));audit.record("CREATE","EmergencyVisit",e.getId().toString(),"created");return e;} @GetMapping public List<EmergencyVisit> list(){return repo.findAll();} @GetMapping("/{id}") public EmergencyVisit get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("EmergencyVisit not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("EmergencyVisit not found: "+id);repo.deleteById(id);audit.record("DELETE","EmergencyVisit",id.toString(),"deleted");} }
